"""Stage stub for programs generated by test/gen and for corpus pipelines.

Every phase is a pure function of the inputs the stage receives: it records
them, type-directed and with each file read as its basename plus a content
digest, in the `seen` output, and draws every other output, file names and
contents, chunk counts and chunk resources from a hash of that record and
the spec's seed, so one pipeline run under several seeds takes different
branches. Two
runtimes that hand the stage the same inputs therefore get the same outputs,
and any difference in what a stage received shows in its outputs.
"""

import hashlib
import json
import os

import martian

with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "spec.json")) as _f:
    SPEC = json.load(_f)

STRUCTS = SPEC["structs"]
FILETYPES = set(SPEC["filetypes"])

INTS = [0, 1, -1, 42, 2**53 + 1, -(2**53) - 1, 2**63 - 1, -(2**63)]
FLOATS = [0.5, -2.25, 1e6, 2.5e6, 1e20, 1e21, 1e-6, 1e-7, 1.5e-6, -0.0, 3.0, 123456789.125]
STRINGS = [
    "", "a", "@mre:file:0/x.txt", "@mre:dir:d", "@mre:", "line1\nline2", "tab\tsep",
    'quote"q', "back\\slash", "ünïcødé ✓", "01", "null", "/tmp/not-a-file", "a~b",
]
KEYS = ["", "~", "a~b", "\n", "é", "～", "\U0001F600", "01", "10", "2", "a", "B", "k k", "x.y"]
BASENAMES = [
    "report.txt", "reads.fastq.gz", "a b.txt", ".hidden", "ünï.dat", "noext",
    "x.tar.gz", "data.json", "01.txt", "~tilde",
]


def ptype(s):
    """Parse a Martian type string into (base, array dims, map dims)."""
    arr = 0
    while s.endswith("[]"):
        s, arr = s[:-2], arr + 1
    if s.startswith("map<") and s.endswith(">"):
        inner, dim = s[4:-1], 1
        while inner.endswith("[]"):
            inner, dim = inner[:-2], dim + 1
        return (inner, arr, dim)
    return (s, arr, 0)


def is_file(base):
    return base == "file" or base in FILETYPES


def has_files(base, seen=()):
    """Whether a value of this base type can hold a file or directory."""
    if base == "path" or is_file(base):
        return True
    if base not in STRUCTS or base in seen:
        return False
    return any(has_files(ptype(ft)[0], seen + (base,)) for _, ft in STRUCTS[base])


def keys_for(base, keys):
    """Martian rejects a file-bearing map whose key is no legal file name."""
    return [k for k in keys if k or not has_files(base)]


def digest(path):
    if os.path.isdir(path):
        h = hashlib.sha256()
        for d, dirs, files in os.walk(path):
            dirs.sort()
            rel = os.path.relpath(d, path)
            h.update(("d %s\n" % rel).encode("utf-8", "surrogateescape"))
            for name in sorted(files):
                with open(os.path.join(d, name), "rb") as f:
                    body = hashlib.sha256(f.read()).hexdigest()
                h.update(("f %s %s\n" % (name, body)).encode("utf-8", "surrogateescape"))
        return "dir:" + h.hexdigest()[:16]
    if os.path.isfile(path):
        with open(path, "rb") as f:
            return "file:" + hashlib.sha256(f.read()).hexdigest()[:16]
    return "missing"


def canon(v, t):
    """The value a stage received, by its declared type, files by content."""
    base, arr, dim = t
    if v is None:
        return None
    if arr:
        if not isinstance(v, list):
            return {"!shape": repr(v)}
        return [canon(e, (base, arr - 1, dim)) for e in v]
    if dim:
        if not isinstance(v, dict):
            return {"!shape": repr(v)}
        return {k: canon(e, (base, dim - 1, 0)) for k, e in v.items()}
    if base in STRUCTS:
        if not isinstance(v, dict):
            return {"!shape": repr(v)}
        fields = STRUCTS[base]
        out = {}
        for name, ft in fields:
            out[name] = canon(v[name], ptype(ft)) if name in v else "!absent"
        extra = sorted(set(v) - set(name for name, _ in fields))
        if extra:
            out["!extra"] = extra
        return out
    if is_file(base) or base == "path":
        if not isinstance(v, str):
            return {"!shape": repr(v)}
        return "%s|%s" % (os.path.basename(v), digest(v))
    return v


def record(values, params):
    return {name: canon(values.get(name), ptype(t)) for name, t in params}


def dumps(v):
    return json.dumps(v, sort_keys=True, separators=(",", ":"))


def hash_of(phase, seen):
    key = "%s/%s/%s" % (SPEC["name"], phase, seen)
    if SPEC.get("seed"):
        key = "%d/%s" % (SPEC["seed"], key)
    return hashlib.sha256(key.encode()).hexdigest()


class Rng(object):
    """A counter-mode sha256 stream: the same seed draws the same values."""

    def __init__(self, seed):
        self.seed, self.n = seed, 0

    def below(self, k):
        self.n += 1
        d = hashlib.sha256(("%s/%d" % (self.seed, self.n)).encode()).hexdigest()
        return int(d[:12], 16) % k

    def pick(self, xs):
        return xs[self.below(len(xs))]


class Maker(object):
    """Draws output values of declared types, writing their files."""

    def __init__(self, rng, tag, used):
        self.r, self.tag, self.used = rng, tag, used
        # Every top-level collection of one invocation gets one shape, so a
        # map call may zip two of them.
        n = self.r.below(5)
        self.top_null = n == 4
        self.top_n = n if n < 4 else 0
        order = sorted(KEYS, key=lambda k: self.r.below(1 << 30))
        self.top_keys = order[: self.top_n]

    def fresh(self, ext):
        name = self.r.pick(BASENAMES)
        if ext and self.r.below(2):
            name = name.split(".")[0] + "." + ext
        while name in self.used:
            name = "%d_%s" % (len(self.used), name)
        self.used.add(name)
        return name

    def write(self, path, label):
        with open(path, "w") as f:
            f.write("%s %s %s\n" % (self.tag, label, self.r.below(1 << 30)))

    def file(self, base, preset):
        if isinstance(preset, str) and self.r.below(3):
            path = preset
        else:
            path = os.fsdecode(martian.make_path(self.fresh("" if base == "file" else base)))
        self.write(path, base)
        return path

    def directory(self, preset):
        if isinstance(preset, str) and self.r.below(3):
            path = preset
        else:
            path = os.fsdecode(martian.make_path(self.fresh("")))
        os.makedirs(path)
        for _ in range(1 + self.r.below(2)):
            name = self.r.pick(BASENAMES)
            self.write(os.path.join(path, name), "entry")
        if self.r.below(3) == 0:
            os.makedirs(os.path.join(path, "empty"))
        return path

    def value(self, t, preset=None, top=False):
        base, arr, dim = t
        collection = arr or dim
        if top and collection:
            if self.top_null:
                return None
        elif (collection or base != "bool") and self.r.below(10) == 0:
            return None
        if arr:
            n = self.top_n if top else self.r.below(3)
            return [self.value((base, arr - 1, dim)) for _ in range(n)]
        if dim:
            keys = self.top_keys if top else [self.r.pick(KEYS) for _ in range(self.r.below(3))]
            return {k: self.value((base, dim - 1, 0)) for k in keys_for(base, keys)}
        return self.scalar(base, preset)

    def scalar(self, base, preset):
        if base == "int":
            return self.r.pick(INTS)
        if base == "float":
            return self.r.pick(FLOATS)
        if base == "string":
            return self.r.pick(STRINGS)
        if base == "bool":
            return self.r.below(2) == 0
        if base == "path":
            return self.directory(preset)
        if is_file(base):
            return self.file(base, preset)
        if base == "map":
            # Martian's untyped map holds any object.
            return {self.r.pick(KEYS): self.r.pick(STRINGS + INTS) for _ in range(self.r.below(3))}
        return {name: self.value(ptype(ft)) for name, ft in STRUCTS[base]}


def maybe_fail(phase, h):
    fail = SPEC.get("fail")
    if fail and fail["phase"] == phase and int(h[:8], 16) % fail["mod"] == 0:
        if fail["kind"] == "assert":
            martian.exit("generated assert in %s %s" % (SPEC["name"], phase))
        raise RuntimeError("generated error in %s %s" % (SPEC["name"], phase))


def fill(outs, params, seen, h):
    current = outs.items()
    used = set(os.path.basename(v) for v in current.values() if isinstance(v, str))
    maker = Maker(Rng(h), "%s:%s" % (SPEC["name"], h[:12]), used)
    for name, t in params:
        if name == "seen":
            setattr(outs, name, seen)
        else:
            setattr(outs, name, maker.value(ptype(t), current.get(name), top=True))


def split(args):
    seen = dumps(record(args.items(), SPEC["in"]))
    h = hash_of("split", seen)
    maybe_fail("split", h)
    r = Rng(h)
    chunks = []
    # Every chunk makes its files in the split's one files dir.
    used = set()
    for i in range(r.below(4)):
        maker = Maker(Rng("%s/%d" % (h, i)), "%s:chunk%d" % (SPEC["name"], i), used)
        chunk = {name: maker.value(ptype(t)) for name, t in SPEC["chunk_in"]}
        chunk["__mem_gb"] = r.pick([1, 0.5, 2])
        chunk["__threads"] = r.pick([1, 2])
        chunks.append(chunk)
    result = {"chunks": chunks}
    if r.below(3) == 0:
        result["join"] = {"__mem_gb": r.pick([1, 1.5, 2]), "__threads": 1}
    return result


def main(args, outs):
    params = SPEC["in"] + SPEC["chunk_in"]
    seen = dumps(record(args.items(), params))
    h = hash_of("main", seen)
    maybe_fail("main", h)
    fill(outs, SPEC["chunk_out"] if SPEC["split"] else SPEC["out"], seen, h)


def join(args, outs, chunk_defs, chunk_outs):
    seen = dumps(
        {
            "args": record(args.items(), SPEC["in"]),
            "chunk_defs": [record(d.items(), SPEC["chunk_in"]) for d in chunk_defs],
            "chunk_outs": [record(o.items(), SPEC["chunk_out"]) for o in chunk_outs],
        }
    )
    h = hash_of("join", seen)
    maybe_fail("join", h)
    fill(outs, SPEC["out"], seen, h)
